#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
using namespace std;
int main() {
    string s, line; while(getline(cin, line)) s += line;
    if (s.empty()) return 0;
    vector<vector<int>> g; size_t i = 0;
    while(i < s.length()){
        if(s[i] == '['){
            size_t j = i + 1; while(j < s.length() && s[j] != '['){ if(s[j] == ']') break; j++; }
            if(j < s.length() && s[j] == '['){
                size_t k = j + 1; while(k < s.length() && s[k] != ']') k++;
                string r = s.substr(j+1, k-j-1); for(char &c : r) if(c == ',') c = ' ';
                stringstream ss(r); int v; vector<int> row; while(ss >> v) row.push_back(v);
                if(!row.empty() || r.find('0') != string::npos) g.push_back(row);
                i = k + 1;
            } else i++;
        } else i++;
    }
    if(g.empty()) return 0;
    int m = g.size(), n = g[0].size(); vector<int> dp(n, 0);
    dp[0] = g[0][0]; for(int j=1; j<n; j++) dp[j] = dp[j-1] + g[0][j];
    for(int r=1; r<m; r++){
        dp[0] += g[r][0];
        for(int c=1; c<n; c++) dp[c] = min(dp[c], dp[c-1]) + g[r][c];
    }
    cout << dp[n-1] << endl; return 0;
}

