import java.util.*;
import java.io.*;
public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder(); String line;
        while((line = br.readLine()) != null) sb.append(line);
        String s = sb.toString().trim(); if(s.isEmpty()) return;
        List<int[]> list = new ArrayList<>(); int i = 0;
        while(i < s.length()){
            if(s.charAt(i) == '['){
                int j = i + 1; while(j < s.length() && s.charAt(j) != '['){ if(s.charAt(j) == ']') break; j++; }
                if(j < s.length() && s.charAt(j) == '['){
                    int k = j + 1; while(k < s.length() && s.charAt(k) != ']') k++;
                    String r = s.substring(j+1, k).replace(",", " ").trim();
                    if(!r.isEmpty()){
                        String[] p = r.split("\\s+"); int[] row = new int[p.length];
                        for(int x=0; x<p.length; x++) row[x] = Integer.parseInt(p[x]);
                        list.add(row);
                    } else if(s.substring(j, k+1).equals("[]")) list.add(new int[0]);
                    i = k + 1;
                } else if(Character.isDigit(s.charAt(i+1))){
                     // Handle [[1]]
                     int k = i + 1; while(k < s.length() && Character.isDigit(s.charAt(k))) k++;
                     list.add(new int[]{Integer.parseInt(s.substring(i+1, k))}); break;
                } else i++;
            } else i++;
        }
        int[][] g = list.toArray(new int[0][]); if(g.length == 0) return;
        int m = g.length, n = g[0].length; int[] dp = new int[n];
        dp[0] = g[0][0]; for(int j=1; j<n; j++) dp[j] = dp[j-1] + g[0][j];
        for(int r=1; r<m; r++){
            dp[0] += g[r][0];
            for(int c=1; c<n; c++) dp[c] = Math.min(dp[c], dp[c-1]) + g[r][c];
        }
        System.out.println(dp[n-1]);
    }
}

